CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,mobile VARCHAR(20) UNIQUE NOT NULL,email TEXT,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'customer',mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE,mfa_secret TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS banks(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,official_url TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,bank_id BIGINT NOT NULL REFERENCES banks(id),loan_type TEXT NOT NULL,product_name TEXT NOT NULL,interest_rate NUMERIC(8,3),min_amount NUMERIC(16,2),max_amount NUMERIC(16,2),max_tenure_months INTEGER,min_income NUMERIC(16,2),min_credit_score INTEGER,employment_type TEXT DEFAULT 'any',source_url TEXT,verified_on DATE,verification_status TEXT NOT NULL DEFAULT 'pending',notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leads(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),name TEXT NOT NULL,mobile VARCHAR(20) NOT NULL,loan_type TEXT NOT NULL,amount NUMERIC(16,2),tenure_months INTEGER,income NUMERIC(16,2),employment_type TEXT,credit_score INTEGER,existing_emi NUMERIC(16,2),message TEXT,eligibility_score INTEGER,status TEXT NOT NULL DEFAULT 'new',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS applications(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),loan_type TEXT NOT NULL,amount NUMERIC(16,2),tenure_months INTEGER,purpose TEXT,status TEXT NOT NULL DEFAULT 'enquiry_received',progress_percent INTEGER NOT NULL DEFAULT 10,bank_name TEXT,bank_reference TEXT,sanction_amount NUMERIC(16,2),sanction_rate NUMERIC(8,3),sanction_tenure_months INTEGER,sanction_date DATE,disbursement_amount NUMERIC(16,2),disbursement_date DATE,admin_note TEXT,callback_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS documents(id BIGSERIAL PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id),doc_type TEXT NOT NULL,original_name TEXT NOT NULL,object_key TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes BIGINT,status TEXT NOT NULL DEFAULT 'uploaded',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS activity(id BIGSERIAL PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,event TEXT NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,ip_address TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),type TEXT NOT NULL DEFAULT 'info',title TEXT NOT NULL,message TEXT NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customer_profiles(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,city TEXT,state TEXT,employment_type TEXT,employer_business_name TEXT,monthly_income NUMERIC(16,2),existing_emi NUMERIC(16,2),credit_score INTEGER,profile_completed BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS application_checklist(id BIGSERIAL PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,item_code TEXT NOT NULL,item_label TEXT NOT NULL,item_type TEXT NOT NULL DEFAULT 'document',required BOOLEAN NOT NULL DEFAULT TRUE,status TEXT NOT NULL DEFAULT 'pending',admin_note TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(application_id,item_code));
CREATE TABLE IF NOT EXISTS case_tasks(id BIGSERIAL PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,title TEXT NOT NULL,owner_user_id BIGINT REFERENCES users(id),due_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'open',priority TEXT NOT NULL DEFAULT 'normal',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS consents(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,consent_type TEXT NOT NULL,granted BOOLEAN NOT NULL DEFAULT FALSE,source TEXT NOT NULL DEFAULT 'web',version TEXT NOT NULL DEFAULT 'v1',ip_address TEXT,user_agent TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,consent_type));
CREATE TABLE IF NOT EXISTS notification_preferences(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,in_app BOOLEAN NOT NULL DEFAULT TRUE,email BOOLEAN NOT NULL DEFAULT FALSE,sms BOOLEAN NOT NULL DEFAULT FALSE,whatsapp BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS grievances(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),category TEXT NOT NULL,subject TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',priority TEXT NOT NULL DEFAULT 'normal',assigned_to BIGINT REFERENCES users(id),resolution_note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),closed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS staff_profiles(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,designation TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE leads ADD COLUMN IF NOT EXISTS assigned_to BIGINT REFERENCES users(id); ALTER TABLE leads ADD COLUMN IF NOT EXISTS next_callback_at TIMESTAMPTZ; ALTER TABLE leads ADD COLUMN IF NOT EXISTS source TEXT DEFAULT 'website'; ALTER TABLE leads ADD COLUMN IF NOT EXISTS note TEXT;
ALTER TABLE applications ADD COLUMN IF NOT EXISTS assigned_to BIGINT REFERENCES users(id); ALTER TABLE applications ADD COLUMN IF NOT EXISTS lead_id BIGINT REFERENCES leads(id);
CREATE TABLE IF NOT EXISTS crm_activities(id BIGSERIAL PRIMARY KEY,lead_id BIGINT REFERENCES leads(id) ON DELETE CASCADE,application_id BIGINT REFERENCES applications(id) ON DELETE CASCADE,actor_user_id BIGINT REFERENCES users(id),activity_type TEXT NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_products_type_status ON products(loan_type,verification_status); CREATE INDEX IF NOT EXISTS idx_applications_user ON applications(user_id); CREATE INDEX IF NOT EXISTS idx_case_tasks_app ON case_tasks(application_id,status); CREATE INDEX IF NOT EXISTS idx_crm_activity_created ON crm_activities(created_at DESC);
